; pages.asm -- chapter 38: where each page is
; generated by gen38.py
        INCLUDE "msx.inc"
        OUTPUT "pages.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
a8      EQU VARS                ; port $A8 as INIT finds it
a8now   EQU VARS + 1            ; and after page 2 is switched
myslot  EQU VARS + 2            ; the cartridge's slot ID
sltwas  EQU VARS + 3            ; SLTTBL for its slot at INIT
sltnow  EQU VARS + 4            ; and after the switch
sum     EQU VARS + 6            ; page 2's 16 KB added up, two bytes
regs    EQU VARS + 8            ; pages.asm: the four secondary registers
ids     EQU VARS + 12           ; pages.asm: the slot ID of each page
SSLOT   EQU $FFFF               ; the secondary slot register, in page 3
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $00          ; Graphic I
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $80          ; colours  $2000
        VDP_REG 4, $00          ; patterns $0000
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: chapter 30's set at 32
        ld hl, shapes
        ld e, 4
        call send
        VRAM_WRITE $2000        ; black ink on white paper
        ld a, $1F
        ld b, 32
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; the names
        ld hl, names
        ld e, 3
        call send
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        in a, (PPI_A)
        ld (a8), a
        ld b, 0                 ; the register of every expanded slot
.slot:  ld hl, EXPTBL
        ld a, l
        add a, b
        ld l, a
        bit 7, (hl)
        jr z, .snext
        ld a, b
        push bc
        call subreg
        pop bc
        ld hl, regs
        ld e, b
        ld d, 0
        add hl, de
        ld (hl), a
.snext: inc b
        ld a, b
        cp 4
        jr nz, .slot
        ld b, 0                 ; the slot ID of every page
.page:  push bc
        call pageid
        pop bc
        ld hl, ids
        ld e, b
        ld d, 0
        add hl, de
        ld (hl), a
        inc b
        ld a, b
        cp 4
        jr nz, .page
        ld d, 3                 ; port $A8
        ld e, 10
        call at
        ld a, (a8)
        call hex
        ld b, 0                 ; each page: its slot, and the ID
.ppr:   ld a, b
        add a, 6
        ld d, a
        ld e, 14
        call at
        ld hl, ids
        ld a, l
        add a, b
        ld l, a
        ld a, (hl)
        push bc
        call putslot
        pop bc
        ld e, 20
        call at
        ld hl, ids
        ld a, l
        add a, b
        ld l, a
        ld a, (hl)
        call hex
        inc b
        ld a, b
        cp 4
        jr nz, .ppr
        ld b, 0                 ; each slot: EXPTBL, SLTTBL, the register
.spr:   ld a, b
        add a, 12
        ld d, a
        ld e, 8
        call at
        ld hl, EXPTBL
        ld a, l
        add a, b
        ld l, a
        ld a, (hl)
        call hex
        ld e, 15
        call at
        ld hl, SLTTBL
        ld a, l
        add a, b
        ld l, a
        ld a, (hl)
        call hex
        ld e, 22
        call at
        ld hl, EXPTBL
        ld a, l
        add a, b
        ld l, a
        bit 7, (hl)
        ld a, '-'
        jr nz, .reg
        out (VDP_DATA), a       ; not expanded: no register
        out (VDP_DATA), a
        jr .snx
.reg:   ld hl, regs
        ld a, l
        add a, b
        ld l, a
        ld a, (hl)
        call hex
.snx:   inc b
        ld a, b
        cp 4
        jr nz, .spr
        VDP_REG 1, $C0          ; the display on, no frame interrupt
.end:   jr .end

; subreg: A = an expanded primary slot -> A = its secondary slot register,
; read at $FFFF through page 3, which hands it back complemented. The
; interrupts must be off: while page 3 shows that slot the RAM is gone, and
; the stack with it. Uses A, B, C
subreg: rrca                    ;  5
        rrca                    ;  5  the slot into bits 6-7
        ld b, a                 ;  5
        in a, (PPI_A)           ; 12
        ld c, a                 ;  5  the slots as they are
        and $3F                 ;  8
        or b                    ;  5
        out (PPI_A), a          ; 12  page 3 shows the slot: no RAM
        ld a, (SSLOT)           ; 14  its register, complemented
        cpl                     ;  5
        ld b, a                 ;  5
        ld a, c                 ;  5
        out (PPI_A), a          ; 12  page 3 back: the RAM again
        ld a, b                 ;  5
        ret                     ; 11

; field: A = a byte of four fields of two bits, one a page, B = a page ->
; A = that page's field. Uses A, C
field:  ld c, b
        inc c
.shift: dec c
        jr z, .done
        rrca
        rrca
        jr .shift
.done:  and 3
        ret

; pageid: B = a page, 0 to 3 -> A = the slot ID it shows, E000SSPP: the
; primary slot from port $A8 and, if EXPTBL says it is expanded, the
; secondary from the slot's own register. Uses A, C, D, E, HL
pageid: in a, (PPI_A)
        call field              ; page B's primary slot
        ld d, a
        ld hl, EXPTBL
        add a, l
        ld l, a
        ld a, (hl)
        and $80                 ; expanded?
        jr z, .primary
        or d
        ld e, a                 ; 1000 00PP
        ld a, d
        push bc
        call subreg             ; the slot's register
        pop bc
        call field              ; page B's secondary slot
        rlca
        rlca                    ; in bits 2-3
        or e
        ret
.primary: ld a, d
        ret

; putslot: A = a slot ID -> "P", or "P-S" for an expanded slot, from the
; address set. Uses A, B
putslot: ld b, a
        and 3
        add a, '0'
        out (VDP_DATA), a       ; the primary slot
        bit 7, b
        ret z
        ld a, '-'
        out (VDP_DATA), a
        ld a, b
        rrca
        rrca
        and 3
        add a, '0'
        out (VDP_DATA), a       ; the secondary
        ret

; at: the next characters go to row D, column E (chapter 30)
at:     ld a, d
        rrca
        rrca
        rrca
        ld c, a
        and $E0
        or e
        out (VDP_CTRL), a
        ld a, c
        and $03
        or $18 | $40
        out (VDP_CTRL), a
        ret

; cells: A as eight boxes from bit 7, a filled box for a 0 (a key held) and
; an empty one for a 1, from the address set. Uses A, B, L
cells:  ld l, a
        ld b, 8
.cell:  ld a, 2
        rlc l                   ; the next bit, into the carry
        jr nc, .put             ; 0: held
        ld a, 1
.put:   out (VDP_DATA), a
        djnz .cell
        ret

; hex: A as two hexadecimal digits, from the address set. Uses A, C
hex:    ld c, a
        rrca
        rrca
        rrca
        rrca
        call .digit
        ld a, c
.digit: and $0F
        add a, '0'
        cp '9' + 1
        jr c, .out
        add a, 'A' - '9' - 1
.out:   out (VDP_DATA), a
        ret

; send: E blocks of 256 bytes from HL to the VDP
send:   ld c, VDP_DATA
        ld b, 0
.otir:  otir
        dec e
        jr nz, .otir
        ret
